import{F as e,I as t,Z as n,t as r}from"./chunks/framework.CJzTmXUT.js";var i=JSON.parse(`{"title":"Migration","description":"","frontmatter":{},"headers":[],"relativePath":"deep-dive/migration.md","filePath":"en/deep-dive/migration.md","lastUpdated":1792296125000}`),a={name:`deep-dive/migration.md`};function o(r,i,a,o,s,c){return n(),e(`div`,null,[...i[0]||=[t(`<h1 id="migration" tabindex="-1">Migration <a class="header-anchor" href="#migration" aria-label="Permalink to “Migration”">​</a></h1><p>The word &quot;migration&quot; stands for two unrelated things.</p><p><strong>Remote Migration</strong> is a user-facing operation: the manual transformation of the remote storage layout that a feature requires, such as turning encryption or <a href="./asymmetric-storage">asymmetric storage</a> on. Sync Engine never performs it automatically, because sync strategies differ per device and a half-applied remote is catastrophic. It is described in the <a href="./../usage/remote-migration">Remote Migration guide</a>.</p><p><strong>Migration</strong>, as used here and in the codebase, means the automatic upgrade of data that Sync Engine itself persisted in an older format, like settings in <code>data.json</code> and IndexedDB stores. It never touches the remote, and it is never something the user triggers.</p><p><strong>For users: opening Obsidian / updating Sync Engine at least once during the window performs the automatic migration. For those requiring human action, please ensure you have performed before the deadline.</strong></p><p>For implementation simplicity, migrations are ad-hoc and time-bounded:</p><ul><li>Write the minimum code that repairs one specific legacy shape. Each one is a plain function that runs on load and deletes itself when it is no longer needed.</li><li>Detect legacy data by its shape. A migration must be a no-op once it has already run.</li><li>Run at the earliest seam where the data is visible and nothing has consumed it yet.</li><li>Persist the result through <code>saveSettings</code>.</li><li>Every migration carries a <code>// TODO: remove after &lt;date&gt;</code> comment which means the deadline for deleting the ad-hoc code.</li></ul><h2 id="ongoing-migrations" tabindex="-1">Ongoing Migrations <a class="header-anchor" href="#ongoing-migrations" aria-label="Permalink to “Ongoing Migrations”">​</a></h2><h3 id="sync-strategies" tabindex="-1">Sync Strategies <a class="header-anchor" href="#sync-strategies" aria-label="Permalink to “Sync Strategies”">​</a></h3><ul><li>Reason: 3.2.0 update unified sync strategy and inclusion / exclusion rules handling into a single list.</li><li>Window: 2026-09-28 to 2026-11-01</li><li>Scope: all users.</li><li>Operation: <code>inclusionRules</code>, <code>exclusionRules</code>, and <code>decider</code> are merged.</li><li>Human action: automatic, no human action needed.</li></ul><h3 id="s3-fetchobjectmeta" tabindex="-1">S3 <code>fetchObjectMeta</code> <a class="header-anchor" href="#s3-fetchobjectmeta" aria-label="Permalink to “S3 fetchObjectMeta”">​</a></h3><ul><li>Reason: 3.3.1 metadata handling rework made the toggle obsolete.</li><li>Window: 2026-10-11 to 2026-10-31</li><li>Scope: all S3 users.</li><li>Operation: the stale <code>fetchObjectMeta</code> key is deleted on module start.</li><li>Human action: automatic, no human action needed.</li></ul><h3 id="url-canonicalization" tabindex="-1">URL Canonicalization <a class="header-anchor" href="#url-canonicalization" aria-label="Permalink to “URL Canonicalization”">​</a></h3><ul><li>Reason: the URL discipline enforcement requires endpoints to be stored in RFC 3986 percent-encoded form instead of whatever the user supplied.</li><li>Window: 2026-10-17 to 2026-11-17</li><li>Scope: WebDAV and S3 users whose endpoint contains one or more characters in literal form whose encoded form differs from its literal form, such as <code>@</code>.</li><li>Operation: the endpoint and the S3 proxy URL are re-encoded, and the IndexedDB stores keyed by the namespace derived from the changed Fs UID are copied to the new name.</li><li>Human action: automatic, no human action needed.</li></ul><h3 id="encryption-master-salt" tabindex="-1">Encryption Master Salt <a class="header-anchor" href="#encryption-master-salt" aria-label="Permalink to “Encryption Master Salt”">​</a></h3><ul><li>Reason: the master salt is derived from the Fs UID, which the URL canonicalization changes. Without a workaround, every file already uploaded with encryption would become undecryptable.</li><li>Window: 2026-10-17 to 2027-02-17</li><li>Scope: users with encryption enabled whose S3/WebDAV endpoint was changed by the URL canonicalization (contains one or more characters in literal form whose encoded form differs from its literal form).</li><li>Operation: the pre-migration endpoint is recorded as <code>legacyEndpoint</code>, so the master salt keeps being derived from the old Fs UID. This workaround will be removed once the window is complete.</li><li>Human action: the affected user need to re-upload the encrypted remote following the <a href="./../usage/remote-migration">Remote Migration guide</a> before the end of the window, since the salt changes back once the workaround is removed.</li></ul>`,16)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};